function applyPermissions(){$$('[data-new-post]').forEach(node=>node.classList.toggle('permission-hidden',!canEditContent()));$$('[data-upload-media]').forEach(node=>node.classList.toggle('permission-hidden',!canEditContent()));el.newIdeaButton?.classList.toggle('permission-hidden',!canEditContent());el.newRecurringButton?.classList.toggle('permission-hidden',!canEditContent());el.newMediaFolderButton?.classList.toggle('permission-hidden',!canEditContent());el.newTemplateButton?.classList.toggle('permission-hidden',!canEditContent());el.emptyNewTemplateButton?.classList.toggle('permission-hidden',!canEditContent());el.saveAsTemplateButton?.classList.toggle('permission-hidden',!canEditContent());el.newCampaignButton?.classList.toggle('permission-hidden',!canEditContent());el.newRequestButton?.classList.toggle('permission-hidden',!canCollaborate());el.newThreadButton?.classList.toggle('permission-hidden',!canCollaborate());el.teamSettingsTab?.classList.toggle('permission-hidden',!hasRole('admin'));el.companySettingsTab?.classList.toggle('permission-hidden',!hasRole('admin'));el.createBackupButton?.classList.toggle('permission-hidden',!hasRole('admin'));document.querySelector('[data-view-link="backups"]')?.classList.toggle('permission-hidden',!hasRole('admin'));el.connectMetaButton?.classList.toggle('permission-hidden',!hasRole('admin'));el.importButton?.classList.toggle('permission-hidden',!hasRole('admin'));el.publishMetaButton?.classList.toggle('permission-hidden',!canPublishContent());el.openAllButton?.classList.toggle('permission-hidden',!canPublishContent());if(!hasRole('admin')&&!document.querySelector('[data-settings-pane="team"]')?.hidden)showSettingsTab('profile')}
function renderAll(){renderDashboard();renderCalendar();renderPostsLibrary();renderTemplates();renderIdeas();renderMediaLibrary();renderCampaigns();renderQueue();renderAccounts();renderNotifications();renderRequests();renderInbox();renderAnalytics();renderActivity();renderBackups();renderSettings();updateCounts();applyPermissions()}
function updateCounts(){const queue=queuePosts();const ready=PLATFORMS.filter(p=>browserSessions[p.id]).length;el.postsNavCount.textContent=state.posts.length;el.templatesNavCount.textContent=state.templates.length;el.ideasNavCount.textContent=state.ideas.filter(item=>item.status!=='ready').length;el.mediaNavCount.textContent=state.media.length;el.notificationsNavCount.textContent=state.notifications.filter(item=>!notificationIsRead(item.id)).length;el.inboxNavCount.textContent=state.threads.filter(thread=>thread.status!=='closed').length;el.requestsNavCount.textContent=state.requests.filter(request=>request.status!=='completed').length;el.calendarNavCount.textContent=state.posts.filter(p=>p.scheduledAt&&p.status!=='published').length;el.queueNavCount.textContent=queue.length;el.accountsNavCount.textContent=ready;el.workspaceStatusText.textContent=`${ready} of ${PLATFORMS.length} ready on this browser`}

function renderDashboard(){
  const now=Date.now(),due=state.posts.filter(p=>p.status!=='published'&&p.scheduledAt&&new Date(p.scheduledAt).getTime()<=now+48*3600000&&new Date(p.scheduledAt).getTime()>=now-24*3600000),scheduled=state.posts.filter(p=>p.status!=='published'&&p.scheduledAt&&new Date(p.scheduledAt)>new Date()),published=state.posts.filter(p=>p.status==='published');
  el.totalPostsStat.textContent=state.posts.length;el.duePostsStat.textContent=due.length;el.scheduledPostsStat.textContent=scheduled.length;el.publishedPostsStat.textContent=published.length;
  const next=sortedPosts().find(p=>p.status!=='published'&&p.scheduledAt&&new Date(p.scheduledAt)>=new Date());if(el.heroNextTitle)el.heroNextTitle.textContent=next?postTitle(next):'Nothing scheduled';if(el.heroNextTime)el.heroNextTime.textContent=next?formatDateTime(next.scheduledAt):'Create a post to start your queue';
  const upcoming=sortedPosts().filter(p=>p.status!=='published'&&new Date(p.scheduledAt)>=new Date()).slice(0,4);el.upcomingList.innerHTML=upcoming.length?upcoming.map(p=>{const d=new Date(p.scheduledAt);return`<article class="upcoming-item" data-edit-post="${p.id}"><div class="date-tile"><small>${d.toLocaleDateString('en-GB',{month:'short'}).toUpperCase()}</small><strong>${d.getDate()}</strong></div><div class="upcoming-copy"><strong>${escapeHtml(postTitle(p))}</strong><small>${d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})} · ${p.platforms.length} channels</small></div>${statusPill(p.status)}</article>`}).join(''):`<div class="empty-state"><p>No upcoming posts. Create one to begin.</p><button class="button button-primary" data-new-post>Create post</button></div>`;
  el.miniAccounts.innerHTML=PLATFORMS.map(p=>`<div class="mini-account"><i class="${browserSessions[p.id]?'ready':''}"></i><span class="network-badge" style="background:${p.color}">${p.badge}</span><strong>${p.name}</strong></div>`).join('');
  el.recentPostsBody.innerHTML=[...state.posts].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,5).map(postRow).join('');bindDynamicPostClicks();
}
function postRow(p){const actions=canEditContent()?`<button type="button" data-edit-post="${p.id}">Edit</button><button class="delete" type="button" data-delete-post="${p.id}">Delete</button>`:`<button type="button" data-edit-post="${p.id}">${canApproveContent()?'Review':'View'}</button>`;return`<tr data-post-row="${p.id}"><td class="post-cell"><strong>${escapeHtml(postTitle(p))}</strong><small>${escapeHtml(normaliseHashtags(p.hashtags)||'No hashtags')}</small></td><td>${platformBadges(p.platforms)}</td><td>${campaignTag(p.campaignId)}</td><td>${escapeHtml(formatDateTime(p.scheduledAt,true))}</td><td>${statusPill(p.status)}</td><td><div class="post-row-actions">${actions}</div></td></tr>`}
function bindDynamicPostClicks(){$$('[data-post-row]').forEach(row=>{if(!row.dataset.bound){row.dataset.bound='1';row.addEventListener('click',event=>{if(event.target.closest('button'))return;openPostModal(row.dataset.postRow)})}});$$('[data-edit-post]').forEach(node=>{if(!node.dataset.bound){node.dataset.bound='1';node.addEventListener('click',event=>{event.stopPropagation();openPostModal(node.dataset.editPost)})}});$$('[data-delete-post]').forEach(button=>{if(!button.dataset.bound){button.dataset.bound='1';button.addEventListener('click',event=>{event.stopPropagation();deletePostById(button.dataset.deletePost)})}});$$('[data-new-post]').forEach(button=>{if(!button.dataset.bound){button.dataset.bound='1';button.addEventListener('click',()=>openPostModal())}})}

function renderCalendar(){const base=new Date(calendarCursor),month=base.getMonth(),year=base.getFullYear(),first=calendarMode==='week'?base:new Date(year,month,1),offset=(first.getDay()+6)%7,start=new Date(first);start.setDate(first.getDate()-offset);const days=calendarMode==='week'?7:42;el.calendarMonthTitle.textContent=calendarMode==='week'?`Week of ${new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(start)}`:new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric'}).format(base);let html='';for(let i=0;i<days;i++){const day=new Date(start);day.setDate(start.getDate()+i);const key=toLocalDate(day),posts=state.posts.filter(p=>p.scheduledAt&&toLocalDate(new Date(p.scheduledAt))===key),other=calendarMode==='month'&&day.getMonth()!==month,today=key===toLocalDate(new Date());html+=`<div class="calendar-day ${other?'other-month':''} ${today?'today':''}" data-calendar-day="${key}"><span class="day-number">${day.getDate()}</span><div class="day-posts">${posts.slice(0,calendarMode==='week'?8:3).map(p=>`<div class="calendar-post ${p.status}" data-edit-post="${p.id}" data-drag-post="${p.id}" draggable="${canEditContent()}" title="${escapeHtml(postTitle(p))}">${escapeHtml(postTitle(p))}</div>`).join('')}${posts.length>(calendarMode==='week'?8:3)?`<span class="more-posts">+${posts.length-(calendarMode==='week'?8:3)} more</span>`:''}</div></div>`}el.calendarGrid.innerHTML=html;const unscheduled=state.posts.filter(p=>!p.scheduledAt);el.unscheduledPosts.innerHTML=unscheduled.map(p=>`<div class="unscheduled-card" data-drag-post="${p.id}" draggable="${canEditContent()}">${escapeHtml(postTitle(p))}</div>`).join('')||'<span class="thread-empty">No unscheduled posts</span>';$$('[data-drag-post]').forEach(node=>node.addEventListener('dragstart',event=>event.dataTransfer.setData('text/post-id',node.dataset.dragPost)));$$('[data-calendar-day]').forEach(day=>{day.addEventListener('dragover',event=>{if(canEditContent()){event.preventDefault();day.classList.add('drag-over')}});day.addEventListener('dragleave',()=>day.classList.remove('drag-over'));day.addEventListener('drop',event=>{event.preventDefault();day.classList.remove('drag-over');reschedulePost(event.dataTransfer.getData('text/post-id'),day.dataset.calendarDay)});day.addEventListener('click',event=>{if(event.target.closest('[data-edit-post]')||!canEditContent())return;openPostModal(null,day.dataset.calendarDay)})});bindDynamicPostClicks()}
async function reschedulePost(id,date){if(!canEditContent())return;const post=state.posts.find(item=>item.id===id);if(!post)return;const old=post.scheduledAt?new Date(post.scheduledAt):null,time=old?old.toTimeString().slice(0,5):(state.company?.working_hours_start||'09:00').slice(0,5),scheduledAt=new Date(`${date}T${time}:00`).toISOString(),result=await db.from('posts').update({scheduled_at:scheduledAt,updated_at:new Date().toISOString(),updated_by:currentUser.id}).eq('id',id);if(result.error){toast(result.error.message,true);return}post.scheduledAt=scheduledAt;renderAll();toast('Post rescheduled.')}

function renderPostsLibrary(){const q=el.postSearch.value.trim().toLowerCase(),status=el.statusFilter.value,channel=el.platformFilter.value;const posts=[...state.posts].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).filter(p=>(status==='all'||p.status===status)&&(channel==='all'||p.platforms.includes(channel))&&(!q||[p.caption,p.hashtags,p.notes,campaign(p.campaignId)?.name].join(' ').toLowerCase().includes(q)));el.allPostsBody.innerHTML=posts.map(postRow).join('');el.postsEmpty.hidden=posts.length>0;bindDynamicPostClicks()}
function renderTemplatePlatformPicker(){el.templatePlatformPicker.innerHTML=PLATFORMS.map(p=>`<label class="platform-option"><input type="checkbox" value="${p.id}" /><span class="network-badge" style="background:${p.color}">${p.badge}</span><strong>${p.name}</strong><i>✓</i></label>`).join('');el.templatePlatformPicker.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{selectedTemplatePlatforms=[...el.templatePlatformPicker.querySelectorAll('input:checked')].map(item=>item.value)}))}
function renderPostTemplateOptions(){el.postTemplateSelect.innerHTML='<option value="">Choose a template…</option>'+state.templates.map(template=>`<option value="${template.id}">${escapeHtml(template.name)}</option>`).join('')}
function renderTemplates(){const q=(el.templateSearch?.value||'').trim().toLowerCase(),campaignFilter=el.templateCampaignFilter?.value||'all',previous=campaignFilter;el.templateCampaignFilter.innerHTML='<option value="all">All campaigns</option><option value="none">No campaign</option>'+state.campaigns.map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('');el.templateCampaignFilter.value=[...el.templateCampaignFilter.options].some(option=>option.value===previous)?previous:'all';const filter=el.templateCampaignFilter.value,items=state.templates.filter(item=>(filter==='all'||(filter==='none'&&!item.campaignId)||item.campaignId===filter)&&(!q||[item.name,item.description,item.caption,item.hashtags].join(' ').toLowerCase().includes(q)));el.templatesEmpty.hidden=items.length>0;el.templateGrid.innerHTML=items.map(item=>`<article class="template-card"><header><span><svg viewBox="0 0 24 24"><path d="M5 3h11l3 3v15H5Z"/><path d="M8 11h8M8 15h8"/></svg></span><div><h3>${escapeHtml(item.name)}</h3><small>${escapeHtml(item.description||'Reusable post template')}</small></div></header><p>${escapeHtml(item.caption||'No caption saved')}</p><div class="template-hashtags">${escapeHtml(normaliseHashtags(item.hashtags)||'No hashtags')}</div><div class="template-meta">${platformBadges(item.platforms)}<small>Used ${item.useCount} times</small></div><div class="template-actions">${canEditContent()?`<button class="use" type="button" data-use-template="${item.id}">Use</button><button type="button" data-edit-template="${item.id}">Edit</button><button class="delete" type="button" data-delete-template="${item.id}">×</button>`:'<button type="button" data-edit-template="'+item.id+'">View</button>'}</div></article>`).join('');$$('[data-use-template]').forEach(button=>button.addEventListener('click',()=>useTemplateInNewPost(button.dataset.useTemplate)));$$('[data-edit-template]').forEach(button=>button.addEventListener('click',()=>openTemplateModal(button.dataset.editTemplate)));$$('[data-delete-template]').forEach(button=>button.addEventListener('click',()=>deleteTemplate(button.dataset.deleteTemplate)))}
function openTemplateModal(id='',seed=null){const item=id?state.templates.find(template=>template.id===id):null;el.templateForm.reset();el.templateId.value=item?.id||'';el.templateName.value=item?.name||seed?.name||'';el.templateDescription.value=item?.description||seed?.description||'';el.templateCaption.value=item?.caption||seed?.caption||'';el.templateHashtags.value=item?.hashtags||seed?.hashtags||'';el.templateCampaign.innerHTML='<option value="">No campaign</option>'+state.campaigns.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');el.templateCampaign.value=item?.campaignId||seed?.campaignId||'';selectedTemplatePlatforms=[...(item?.platforms||seed?.platforms||['instagram','facebook'])];el.templatePlatformPicker.querySelectorAll('input').forEach(input=>input.checked=selectedTemplatePlatforms.includes(input.value));const editable=canEditContent();el.templateForm.querySelectorAll('input:not([type="hidden"]),textarea,select').forEach(field=>field.disabled=!editable);el.templateForm.querySelector('[type="submit"]').hidden=!editable;el.deleteTemplateButton.hidden=!item||!editable;el.templateModalTitle.textContent=item?(editable?'Edit post template':'View post template'):'New post template';openModal(el.templateModal);setTimeout(()=>el.templateName.focus(),50)}
function openTemplateFromPost(){if(!canEditContent())return;openTemplateModal('',{name:'',description:'Created from a post',caption:el.postCaption.value,hashtags:el.postHashtags.value,campaignId:el.postCampaign.value,platforms:[...selectedPlatforms]})}
async function saveTemplate(event){event.preventDefault();if(!canEditContent())return;const existing=state.templates.find(item=>item.id===el.templateId.value),now=new Date().toISOString(),record={id:existing?.id,name:el.templateName.value.trim(),description:el.templateDescription.value.trim(),caption:el.templateCaption.value.trim(),hashtags:el.templateHashtags.value.trim(),platforms:[...selectedTemplatePlatforms],campaignId:el.templateCampaign.value,createdBy:existing?.createdBy||currentUser.id,useCount:existing?.useCount||0,createdAt:existing?.createdAt||now,updatedAt:now};if(!record.name)return;const query=existing?db.from('post_templates').update(templateToDb(record)).eq('id',existing.id):db.from('post_templates').insert(templateToDb(record)).select().single(),result=await query;if(result.error){toast(`Could not save template: ${result.error.message}`,true);return}if(existing)state.templates=state.templates.map(item=>item.id===existing.id?record:item);else state.templates.unshift(templateFromDb(result.data));closeModal(el.templateModal);renderAll();toast(existing?'Template updated.':'Template created.')}
async function deleteTemplate(id){if(!canEditContent())return;const item=state.templates.find(template=>template.id===id);if(!item||!confirm(`Delete template “${item.name}”?`))return;const result=await db.from('post_templates').delete().eq('id',id);if(result.error){toast(result.error.message,true);return}state.templates=state.templates.filter(template=>template.id!==id);if(el.templateId.value===id)closeModal(el.templateModal);renderAll();toast('Template deleted.')}
async function deleteCurrentTemplate(){if(el.templateId.value)await deleteTemplate(el.templateId.value)}
function applySelectedTemplate(){const item=state.templates.find(template=>template.id===el.postTemplateSelect.value);if(item)applyTemplateToPost(item,true)}
async function useTemplateInNewPost(id){const item=state.templates.find(template=>template.id===id);if(!item)return;openPostModal();applyTemplateToPost(item,true)}
async function applyTemplateToPost(item,increment){el.postCaption.value=item.caption;el.postHashtags.value=item.hashtags;selectedPlatforms=[...item.platforms];el.platformPicker.querySelectorAll('input').forEach(input=>input.checked=selectedPlatforms.includes(input.value));el.postCampaign.value=state.campaigns.some(c=>c.id===item.campaignId)?item.campaignId:'';el.postTemplateSelect.value=item.id;updateCaptionCount();if(increment&&canEditContent()){item.useCount++;await db.from('post_templates').update({use_count:item.useCount,updated_at:new Date().toISOString()}).eq('id',item.id)}toast(`Template “${item.name}” applied.`)}
function renderRecurringDayOptions(){const weekly=el.recurringFrequency.value==='weekly',current=el.recurringDay.value;el.recurringDay.innerHTML=weekly?['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((name,index)=>`<option value="${index}">${name}</option>`).join(''):Array.from({length:28},(_,index)=>`<option value="${index+1}">Day ${index+1}</option>`).join('');if([...el.recurringDay.options].some(option=>option.value===current))el.recurringDay.value=current}
function openRecurringModal(id=''){if(!canEditContent())return;const item=state.recurring.find(schedule=>schedule.id===id);el.recurringForm.reset();el.recurringId.value=item?.id||'';el.recurringName.value=item?.name||'';el.recurringTemplate.innerHTML=state.templates.map(template=>`<option value="${template.id}">${escapeHtml(template.name)}</option>`).join('');el.recurringTemplate.value=item?.templateId||state.templates[0]?.id||'';el.recurringFrequency.value=item?.frequency||'weekly';renderRecurringDayOptions();el.recurringDay.value=String(item?.frequency==='monthly'?item.dayOfMonth:(item?.weekday??1));el.recurringTime.value=(item?.time||'09:00').slice(0,5);el.recurringEnd.value=item?.endDate||'';el.recurringActive.checked=item?.active??true;el.deleteRecurringButton.hidden=!item;el.recurringModalTitle.textContent=item?'Edit recurring schedule':'Recurring schedule';el.recurringList.innerHTML=state.recurring.map(schedule=>`<article class="recurring-item"><div><strong>${escapeHtml(schedule.name)}</strong><small>${schedule.frequency} · Next ${formatDateTime(schedule.nextRunAt,true)} · ${schedule.active?'Active':'Paused'}</small></div><button type="button" data-edit-recurring="${schedule.id}">Edit</button></article>`).join('');$$('[data-edit-recurring]').forEach(button=>button.addEventListener('click',()=>openRecurringModal(button.dataset.editRecurring)));openModal(el.recurringModal)}
function nextRecurringDate(frequency,day,time){const now=new Date(),target=new Date();if(frequency==='weekly'){const delta=(Number(day)-now.getDay()+7)%7||7;target.setDate(now.getDate()+delta)}else{target.setMonth(now.getMonth()+(now.getDate()>=Number(day)?1:0),Number(day))}const[hour,minute]=time.split(':').map(Number);target.setHours(hour,minute,0,0);return target.toISOString()}
async function saveRecurring(event){event.preventDefault();if(!canEditContent()||!el.recurringTemplate.value)return;const existing=state.recurring.find(item=>item.id===el.recurringId.value),frequency=el.recurringFrequency.value,day=Number(el.recurringDay.value),now=new Date().toISOString(),record={name:el.recurringName.value.trim(),template_id:el.recurringTemplate.value,frequency,weekday:frequency==='weekly'?day:null,day_of_month:frequency==='monthly'?day:null,publish_time:el.recurringTime.value,next_run_at:existing?.nextRunAt||nextRecurringDate(frequency,day,el.recurringTime.value),end_date:el.recurringEnd.value||null,active:el.recurringActive.checked,created_by:currentUser.id,updated_at:now};const result=existing?await db.from('recurring_schedules').update(record).eq('id',existing.id):await db.from('recurring_schedules').insert(record).select().single();if(result.error){toast(result.error.message,true);return}if(existing)state.recurring=state.recurring.map(item=>item.id===existing.id?recurringFromDb({...record,id:existing.id,created_at:existing.createdAt}):item);else state.recurring.push(recurringFromDb(result.data));closeModal(el.recurringModal);renderAll();toast('Recurring schedule saved.')}
async function deleteRecurring(){const id=el.recurringId.value;if(!id||!confirm('Delete this recurring schedule?'))return;const result=await db.from('recurring_schedules').delete().eq('id',id);if(result.error){toast(result.error.message,true);return}state.recurring=state.recurring.filter(item=>item.id!==id);closeModal(el.recurringModal);renderAll()}
function renderIdeas(){const statuses=[['idea','Idea'],['research','Research'],['writing','Writing'],['review','Review'],['ready','Ready']],priorities={low:'#8e949a',normal:'#356fd5',high:'#d99a12',urgent:'#ef111b'};el.ideasBoard.innerHTML=statuses.map(([status,label])=>{const items=state.ideas.filter(item=>item.status===status);return`<section class="idea-column"><header><h3>${label}</h3><span>${items.length}</span></header><div class="idea-column-list">${items.map(item=>`<article class="idea-card" style="--priority:${priorities[item.priority]}" data-idea-id="${item.id}"><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.description||item.notes||'No details')}</p><small>${escapeHtml(item.assignedTo||'Unassigned')} · ${item.priority}</small></article>`).join('')}</div></section>`}).join('');$$('[data-idea-id]').forEach(card=>card.addEventListener('click',()=>openIdeaModal(card.dataset.ideaId)))}
function openIdeaModal(id=''){const item=state.ideas.find(idea=>idea.id===id);el.ideaForm.reset();el.ideaId.value=item?.id||'';el.ideaTitle.value=item?.title||'';el.ideaDescription.value=item?.description||'';el.ideaStatus.value=item?.status||'idea';el.ideaPriority.value=item?.priority||'normal';el.ideaAssignee.value=item?.assignedTo||'';el.ideaCampaign.innerHTML='<option value="">No campaign</option>'+state.campaigns.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('');el.ideaCampaign.value=item?.campaignId||'';el.ideaNotes.value=item?.notes||'';el.deleteIdeaButton.hidden=!item||!canEditContent();el.convertIdeaButton.hidden=!item||!canEditContent()||Boolean(item.convertedPostId);const editable=canEditContent();el.ideaForm.querySelectorAll('input:not([type="hidden"]),textarea,select').forEach(field=>field.disabled=!editable);el.ideaForm.querySelector('[type="submit"]').hidden=!editable;el.ideaModalTitle.textContent=item?(editable?'Edit content idea':'View content idea'):'New content idea';openModal(el.ideaModal)}
async function saveIdea(event){event.preventDefault();if(!canEditContent())return;const existing=state.ideas.find(item=>item.id===el.ideaId.value),now=new Date().toISOString(),record={title:el.ideaTitle.value.trim(),description:el.ideaDescription.value.trim(),status:el.ideaStatus.value,priority:el.ideaPriority.value,assigned_to_email:el.ideaAssignee.value.trim().toLowerCase()||null,campaign_id:el.ideaCampaign.value||null,notes:el.ideaNotes.value.trim(),created_by:existing?.createdBy||currentUser.id,created_at:existing?.createdAt||now,updated_at:now};const result=existing?await db.from('content_ideas').update(record).eq('id',existing.id):await db.from('content_ideas').insert(record).select().single();if(result.error){toast(result.error.message,true);return}if(existing)state.ideas=state.ideas.map(item=>item.id===existing.id?ideaFromDb({...record,id:existing.id}):item);else state.ideas.unshift(ideaFromDb(result.data));closeModal(el.ideaModal);renderAll();toast(existing?'Idea updated.':'Idea added to the board.')}
