async function createMediaFolder(){if(!canEditContent())return;const name=prompt('Folder name');if(!name?.trim())return;const result=await db.from('media_folders').insert({name:name.trim(),created_by:currentUser.id}).select().single();if(result.error){toast(result.error.message,true);return}state.folders.push(folderFromDb(result.data));renderMediaLibrary();toast('Media folder created.')}
