async function hydrateMediaPreviews(items){for(const item of items.filter(x=>x.type==='image')){const holder=document.querySelector(`[data-media-preview="${item.id}"]`);if(!holder)continue;const url=await getMediaSignedUrl(item);if(url&&holder.isConnected)holder.innerHTML=`<img src="${url}" alt="${escapeHtml(item.name)}" loading="lazy" /><i>IMAGE</i>`}}
function renderMediaOptions(){const current=selectedMediaId;el.postMediaSelect.innerHTML='<option value="">No media selected</option>'+state.media.map(item=>`<option value="${item.id}">${escapeHtml(item.name)} · ${formatBytes(item.size)}</option>`).join('');el.postMediaSelect.value=state.media.some(item=>item.id===current)?current:'';selectedMediaId=el.postMediaSelect.value}
function updateSelectedMediaInfo(){const item=state.media.find(x=>x.id===selectedMediaId);el.selectedMediaInfo.innerHTML=item?`<svg viewBox="0 0 24 24">${item.type==='video'?'<path d="M4 6h16v12H4Z"/><path d="m10 9 5 3-5 3Z"/>':'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m4 17 5-5 3.5 3.5 2-2L20 19"/>'}</svg><div><strong>${escapeHtml(item.name)}</strong><small>${item.type} · ${formatBytes(item.size)}</small></div>`:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="m4 17 5-5 3.5 3.5 2-2L20 19"/></svg><div><strong>No media selected</strong><small>Choose an optimised library file</small></div>'}
function openMediaUploadModal(){queuedMediaFiles=[];el.mediaUploadInput.value='';el.mediaUploadQueue.innerHTML='';el.mediaUploadError.textContent='';el.startMediaUploadButton.disabled=true;openModal(el.mediaUploadModal)}
function queueMediaFiles(files){const accepted=[];for(const file of files){const image=['image/jpeg','image/png','image/webp'].includes(file.type),video=['video/mp4','video/webm','video/quicktime'].includes(file.type);if(!image&&!video)continue;if(video&&file.size>52428800){el.mediaUploadError.textContent=`${file.name} is larger than the 50 MB video limit.`;continue}if(image&&file.size>26214400){el.mediaUploadError.textContent=`${file.name} is too large to optimise in the browser.`;continue}accepted.push(file)}queuedMediaFiles=accepted;el.startMediaUploadButton.disabled=!accepted.length;el.mediaUploadQueue.innerHTML=accepted.map((file,index)=>`<div class="upload-queue-item" data-upload-row="${index}"><span>${file.type.startsWith('video/')?'VIDEO':'IMAGE'}</span><div><strong>${escapeHtml(file.name)}</strong><small>${formatBytes(file.size)} · waiting</small></div><i></i></div>`).join('')}
async function optimiseImage(file){const bitmap=await createImageBitmap(file),scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),width=Math.max(1,Math.round(bitmap.width*scale)),height=Math.max(1,Math.round(bitmap.height*scale)),canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d',{alpha:false});context.drawImage(bitmap,0,0,width,height);bitmap.close?.();const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('Image compression failed.')),'image/webp',.78));return{blob,width,height,mime:'image/webp',name:file.name.replace(/\.[^.]+$/, '')+'.webp'}}
