async function savePostFromForm(event){event.preventDefault();if(!canEditContent()){toast('Editor permission is required.',true);return}const caption=el.postCaption.value.trim();if(!caption){el.postFormError.textContent='Add a caption before saving.';return}if(!selectedPlatforms.length){el.postFormError.textContent='Select at least one social channel.';return}if(!el.postDate.value||!el.postTime.value){el.postFormError.textContent='Choose a publishing date and time.';return}if(el.postLink.value.trim()){try{new URL(el.postLink.value.trim())}catch{el.postFormError.textContent='Enter a complete link beginning with http:// or https://';return}}
  const existing=state.posts.find(p=>p.id===el.postId.value),media=state.media.find(item=>item.id===selectedMediaId),now=new Date().toISOString(),record={id:existing?.id||uid('post'),caption,link:state.company?.website_url||DEFAULT_POST_URL,hashtags:el.postHashtags.value.trim(),notes:el.postNotes.value.trim(),platforms:[...selectedPlatforms],scheduledAt:new Date(`${el.postDate.value}T${el.postTime.value}:00`).toISOString(),status:el.postStatus.value,campaignId:el.postCampaign.value,mediaId:media?.id||'',mediaName:media?.name||'',createdBy:existing?.createdBy||currentUser.id,createdAt:existing?.createdAt||now,updatedAt:now},submit=el.postForm.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Saving…';const{error}=await db.from('posts').upsert(postToDb(record));submit.disabled=false;submit.textContent='Save post';if(error){el.postFormError.textContent=`Could not save: ${error.message}`;return}if(record.status==='approval'&&existing?.status!=='approval')await db.from('post_approval_events').insert({post_id:record.id,event_type:'submitted',comment:'Submitted for approval',from_status:existing?.status||'new',to_status:'approval',actor_id:currentUser.id,actor_name:currentDisplayName,actor_email:currentUser.email});if(existing)state.posts=state.posts.map(p=>p.id===existing.id?record:p);else state.posts.push(record);closeModal(el.postModal);renderAll();toast(existing?'Post updated for the team.':'Post added to the shared CRM.')}
async function deletePostById(id){if(!canEditContent()){toast('Editor permission is required to delete posts.',true);return}const post=state.posts.find(item=>item.id===id);if(!post||!confirm(`Delete this post permanently?\n\n${postTitle(post)}`))return;const buttons=$$(`[data-delete-post="${id}"]`);buttons.forEach(button=>button.disabled=true);if(el.postId.value===id)el.deletePostButton.disabled=true;const{error}=await db.from('posts').delete().eq('id',id);buttons.forEach(button=>button.disabled=false);el.deletePostButton.disabled=false;if(error){toast(`Could not delete post: ${error.message}`,true);return}state.posts=state.posts.filter(item=>item.id!==id);state.requests=state.requests.map(request=>request.relatedPostId===id?{...request,relatedPostId:''}:request);if(el.postId.value===id)closeModal(el.postModal);renderAll();toast('Post permanently deleted.')}
async function deleteCurrentPost(){const id=el.postId.value;if(id)await deletePostById(id)}
function renderApprovalTimeline(postId){el.approvalSection.hidden=!postId;if(!postId)return;const events=state.approvalEvents.filter(event=>event.postId===postId).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)),colours={comment:'#356fd5',approved:'#18a56e',changes_requested:'#ef111b',submitted:'#8a54cf',status_changed:'#d99a12'};el.approvalTimeline.innerHTML=events.length?events.map(event=>`<article class="approval-event" style="--event-colour:${colours[event.type]||'#71747b'}"><i></i><div><strong>${escapeHtml(event.actorName)} · ${escapeHtml(event.type.replaceAll('_',' '))}</strong>${event.comment?`<p>${escapeHtml(event.comment)}</p>`:''}<small>${event.fromStatus&&event.toStatus?`${event.fromStatus} → ${event.toStatus} · `:''}${formatDateTime(event.createdAt,true)}</small></div></article>`).join(''):'<div class="thread-empty">No approval activity yet.</div>';el.approvalCommentBox.hidden=!canCollaborate()}
async function addApprovalComment(){const postId=el.postId.value,comment=el.approvalComment.value.trim();if(!postId||!comment||!canCollaborate())return;const result=await db.rpc('add_approval_comment',{p_post_id:postId,p_comment:comment});if(result.error){toast(result.error.message,true);return}el.approvalComment.value='';await loadCloudData();renderApprovalTimeline(postId);toast('Review comment added.')}
async function reviewPost(decision){const id=el.postId.value;if(!id||!canApproveContent())return;const reason=el.approvalComment.value.trim();if(decision==='changes'&&!reason){toast('Add a reason before requesting changes.',true);return}el.approvePostButton.disabled=true;el.requestChangesButton.disabled=true;const{data,error}=await db.rpc('set_post_approval_with_reason',{p_post_id:id,p_decision:decision,p_reason:reason});el.approvePostButton.disabled=false;el.requestChangesButton.disabled=false;if(error){toast(`Could not update approval: ${error.message}`,true);return}const post=state.posts.find(item=>item.id===id);if(post)post.status=data;el.approvalComment.value='';await loadCloudData();closeModal(el.postModal);renderAll();toast(decision==='approve'?'Post approved and ready to publish.':'Post returned to draft with feedback.')}

function renderColourPicker(){el.colourPicker.innerHTML=COLOURS.map((c,i)=>`<button class="colour-button ${i===0?'active':''}" style="--colour:${c}" data-colour="${c}" type="button" aria-label="Choose colour"></button>`).join('');$$('[data-colour]').forEach(b=>b.addEventListener('click',()=>{selectedCampaignColour=b.dataset.colour;$$('[data-colour]').forEach(x=>x.classList.toggle('active',x===b))}))}
function openCampaignModal(id=null){const c=id?campaign(id):null;el.campaignForm.reset();el.campaignId.value=c?.id||'';el.campaignName.value=c?.name||'';el.campaignDescription.value=c?.description||'';selectedCampaignColour=c?.colour||COLOURS[0];$$('[data-colour]').forEach(b=>b.classList.toggle('active',b.dataset.colour===selectedCampaignColour));const editable=canEditContent();el.deleteCampaignButton.hidden=!c||!editable;el.campaignForm.querySelectorAll('input:not([type="hidden"]),textarea,button[data-colour]').forEach(field=>field.disabled=!editable);el.campaignForm.querySelector('[type="submit"]').hidden=!editable;openModal(el.campaignModal);setTimeout(()=>el.campaignName.focus(),60)}
async function saveCampaignFromForm(event){event.preventDefault();if(!canEditContent()){toast('Editor permission is required.',true);return}const name=el.campaignName.value.trim();if(!name)return;const existing=campaign(el.campaignId.value),now=new Date().toISOString(),record={id:existing?.id||uid('camp'),name,description:el.campaignDescription.value.trim(),colour:selectedCampaignColour,createdAt:existing?.createdAt||now,updatedAt:now},submit=el.campaignForm.querySelector('[type="submit"]');submit.disabled=true;const{error}=await db.from('campaigns').upsert(campaignToDb(record));submit.disabled=false;if(error){toast(`Could not save campaign: ${error.message}`,true);return}if(existing)state.campaigns=state.campaigns.map(c=>c.id===existing.id?record:c);else state.campaigns.push(record);closeModal(el.campaignModal);renderAll();toast(existing?'Campaign updated for the team.':'Campaign created.')}
async function deleteCurrentCampaign(){if(!canEditContent()){toast('Editor permission is required.',true);return}const id=el.campaignId.value;if(!id||!confirm('Delete this campaign? Its posts will remain uncategorised.'))return;el.deleteCampaignButton.disabled=true;const{error}=await db.from('campaigns').delete().eq('id',id);el.deleteCampaignButton.disabled=false;if(error){toast(`Could not delete campaign: ${error.message}`,true);return}state.campaigns=state.campaigns.filter(c=>c.id!==id);state.posts=state.posts.map(p=>p.campaignId===id?{...p,campaignId:'',updatedAt:new Date().toISOString()}:p);closeModal(el.campaignModal);renderAll();toast('Campaign deleted.')}

function openPublishModal(id){const post=state.posts.find(p=>p.id===id);if(!post)return;publishingPostId=id;const media=state.media.find(item=>item.id===post.mediaId);el.publishMediaReference.hidden=!media;el.publishMediaName.textContent=media?.name||'';const hasConnectedMeta=post.platforms.some(pid=>['facebook','instagram'].includes(pid)&&state.connections.some(connection=>connection.platform===pid&&connection.status==='connected'));el.publishMetaButton.disabled=!hasConnectedMeta;el.publishMetaButton.textContent=hasConnectedMeta?'Publish connected Meta accounts':'Connect Meta in Settings first';el.publishModalTitle.textContent=isDue(post)?'This post is ready':'Prepare publishing session';el.publishCaptionPreview.textContent=buildCaption(post)||'No caption';el.publishResults.innerHTML=post.platforms.map(pid=>{const p=platform(pid);return`<div class="publish-result"><span class="network-badge" style="background:${p.color}">${p.badge}</span><div><strong>${p.name}</strong><small>${browserSessions[pid]?'This browser is marked ready':'Sign in once on this browser before publishing'}</small></div><a href="${p.composer(post)}" target="_blank" rel="noopener noreferrer">Open</a></div>`}).join('');openModal(el.publishModal)}
async function openPublishingMedia(){const post=state.posts.find(p=>p.id===publishingPostId),media=state.media.find(item=>item.id===post?.mediaId);if(!media)return;const url=await getMediaSignedUrl(media);if(url)window.open(url,'_blank','noopener')}
async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();return ok}}
async function copyPublishingCaption(){const post=state.posts.find(p=>p.id===publishingPostId);if(!post)return;const ok=await copyText(buildCaption(post));toast(ok?'Caption copied.':'Could not copy automatically.',!ok)}
async function openPublishingPages(){if(!canPublishContent()){toast('Approver permission is required to publish.',true);return}const post=state.posts.find(p=>p.id===publishingPostId);if(!post)return;const copyPromise=copyText(buildCaption(post));let opened=0;post.platforms.forEach(pid=>{const p=platform(pid);try{const tab=window.open('about:blank','_blank');if(tab){tab.opener=null;tab.location.href=p.composer(post);opened++}}catch{}});const copied=await copyPromise;toast(`${opened} of ${post.platforms.length} pages opened${copied?' and caption copied':''}.`,opened<post.platforms.length)}
async function markPublishingPostComplete(){const post=state.posts.find(p=>p.id===publishingPostId);if(!post)return;const updatedAt=new Date().toISOString();el.markPublishedButton.disabled=true;const{error}=await db.from('posts').update({status:'published',updated_at:updatedAt,updated_by:currentUser.id}).eq('id',post.id);el.markPublishedButton.disabled=false;if(error){toast(`Could not update post: ${error.message}`,true);return}post.status='published';post.updatedAt=updatedAt;closeModal(el.publishModal);renderAll();toast('Post marked as published for the team.')}

function notificationIsRead(id){return state.notificationReads.some(item=>item.notification_id===id&&item.user_id===currentUser?.id)}
function notificationVisual(type){const values={approval:['#8a54cf','<path d="m5 12 4 4L19 6"/><circle cx="12" cy="12" r="9"/>'],request:['#356fd5','<path d="M6 3h12v18H6Z"/><path d="M9 8h6M9 12h6"/>'],inbox:['#18a56e','<path d="M4 5h16v12H8l-4 4Z"/><path d="M8 9h8"/>'],due:['#d99a12','<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'],overdue:['#ef111b','<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 16h.01"/>'],role:['#6c57c7','<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>']};return values[type]||['#71747b','<path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18"/>']}
function notificationMarkup(item){const read=notificationIsRead(item.id),visual=notificationVisual(item.type);return`<article class="notification-item ${read?'':'unread'}" data-notification-id="${item.id}" style="--notification-colour:${visual[0]}"><span class="notification-icon"><svg viewBox="0 0 24 24">${visual[1]}</svg></span><div class="notification-copy"><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.body)}</p><small>${formatDateTime(item.createdAt,true)}</small></div><button type="button" data-toggle-notification="${item.id}" aria-label="${read?'Mark unread':'Mark read'}">${read?'○':'●'}</button></article>`}
function renderNotifications(){const unread=state.notifications.filter(item=>!notificationIsRead(item.id)).length;el.notificationBellCount.hidden=!unread;el.notificationBellCount.textContent=unread>99?'99+':unread;el.notificationsNavCount.textContent=unread;el.notificationDropdownSummary.textContent=unread?`${unread} unread`:'You’re all caught up';const recent=state.notifications.slice(0,8);el.notificationDropdownList.innerHTML=recent.length?recent.map(notificationMarkup).join(''):'<div class="thread-empty">No notifications yet.</div>';const type=el.notificationTypeFilter.value,items=state.notifications.filter(item=>(notificationFilter==='all'||!notificationIsRead(item.id))&&(type==='all'||item.type===type));el.notificationsEmpty.hidden=items.length>0;el.notificationCentreList.innerHTML=items.map(notificationMarkup).join('');$$('[data-notification-id]').forEach(node=>{if(!node.dataset.bound){node.dataset.bound='1';node.addEventListener('click',event=>{if(event.target.closest('[data-toggle-notification]'))return;openNotification(node.dataset.notificationId)})}});$$('[data-toggle-notification]').forEach(button=>{if(!button.dataset.bound){button.dataset.bound='1';button.addEventListener('click',event=>{event.stopPropagation();toggleNotificationRead(button.dataset.toggleNotification)})}})}
async function markNotificationRead(id){if(notificationIsRead(id))return;const result=await db.from('notification_reads').upsert({notification_id:id,user_id:currentUser.id,read_at:new Date().toISOString()});if(!result.error)state.notificationReads.push({notification_id:id,user_id:currentUser.id,read_at:new Date().toISOString()})}
async function toggleNotificationRead(id){if(notificationIsRead(id)){const result=await db.from('notification_reads').delete().eq('notification_id',id).eq('user_id',currentUser.id);if(!result.error)state.notificationReads=state.notificationReads.filter(item=>!(item.notification_id===id&&item.user_id===currentUser.id))}else await markNotificationRead(id);renderNotifications();updateCounts()}
async function markAllNotificationsRead(){const unread=state.notifications.filter(item=>!notificationIsRead(item.id));if(!unread.length)return;const rows=unread.map(item=>({notification_id:item.id,user_id:currentUser.id,read_at:new Date().toISOString()})),result=await db.from('notification_reads').upsert(rows);if(result.error){toast(result.error.message,true);return}state.notificationReads.push(...rows);renderNotifications();updateCounts();toast('All notifications marked as read.')}
async function openNotification(id){const item=state.notifications.find(notification=>notification.id===id);if(!item)return;await markNotificationRead(id);el.notificationDropdown.hidden=true;renderNotifications();updateCounts();if(item.targetView)showView(item.targetView);if(item.entityType==='post'&&item.entityId&&state.posts.some(post=>post.id===item.entityId))openPostModal(item.entityId);if(item.entityType==='thread'&&item.entityId){activeThreadId=item.entityId;showView('inbox');renderInbox()}}
function renderRequests(){const open=state.requests.filter(r=>r.status==='open').length,progress=state.requests.filter(r=>r.status==='in_progress').length,completed=state.requests.filter(r=>r.status==='completed').length;el.openRequestsStat.textContent=open;el.progressRequestsStat.textContent=progress;el.completedRequestsStat.textContent=completed;const status=el.requestStatusFilter.value,type=el.requestTypeFilter.value,items=[...state.requests].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).filter(r=>(status==='all'||r.status===status)&&(type==='all'||r.type===type));el.requestsEmpty.hidden=items.length>0;const colours={low:'#8e949a',normal:'#356fd5',high:'#d99a12',urgent:'#ef111b'};el.requestList.innerHTML=items.map(r=>`<article class="request-card" data-edit-request="${r.id}"><i class="priority-bar" style="--priority:${colours[r.priority]}"></i><div class="request-copy"><strong>${escapeHtml(r.title)}</strong><p>${escapeHtml(r.details||'No additional details.')}</p><small>Requested by ${escapeHtml(r.requestedByName)} · ${formatDateTime(r.createdAt,true)}${r.assignedTo?` · Assigned to ${escapeHtml(r.assignedTo)}`:''}</small></div><div class="request-side"><span class="request-type-badge">${r.type==='content_approval'?'Content approval':'Information'}</span><select class="request-status-select" data-request-status="${r.id}" ${!canCollaborate()?'disabled':''}><option value="open" ${r.status==='open'?'selected':''}>Open</option><option value="in_progress" ${r.status==='in_progress'?'selected':''}>In progress</option><option value="completed" ${r.status==='completed'?'selected':''}>Completed</option></select></div></article>`).join('');$$('[data-edit-request]').forEach(card=>card.addEventListener('click',event=>{if(event.target.closest('[data-request-status]'))return;openRequestModal(card.dataset.editRequest)}));$$('[data-request-status]').forEach(select=>select.addEventListener('change',()=>updateRequestStatus(select.dataset.requestStatus,select.value)))}
function openRequestModal(id=''){const item=state.requests.find(r=>r.id===id);el.requestForm.reset();el.requestId.value=item?.id||'';el.requestType.value=item?.type||'information';el.requestPriority.value=item?.priority||'normal';el.requestTitle.value=item?.title||'';el.requestDetails.value=item?.details||'';el.requestAssignee.value=item?.assignedTo||'';el.requestRelatedPost.innerHTML='<option value="">No related post</option>'+state.posts.map(post=>`<option value="${post.id}">${escapeHtml(postTitle(post))}</option>`).join('');el.requestRelatedPost.value=item?.relatedPostId||'';const editable=canCollaborate();el.deleteRequestButton.hidden=!item||!(hasRole('admin')||item?.requestedBy===currentUser?.id);el.requestForm.querySelectorAll('input:not([type="hidden"]),textarea,select').forEach(field=>field.disabled=!editable);el.requestForm.querySelector('[type="submit"]').hidden=!editable;openModal(el.requestModal);setTimeout(()=>el.requestTitle.focus(),50)}
async function saveRequest(event){event.preventDefault();if(!canCollaborate()){toast('Your role is read-only.',true);return}const existing=state.requests.find(r=>r.id===el.requestId.value),now=new Date().toISOString(),record={id:existing?.id,title:el.requestTitle.value.trim(),details:el.requestDetails.value.trim(),request_type:el.requestType.value,priority:el.requestPriority.value,status:existing?.status||'open',requested_by:existing?.requestedBy||currentUser.id,requested_by_email:existing?.requestedByEmail||currentUser.email,requested_by_name:existing?.requestedByName||currentDisplayName,assigned_to_email:el.requestAssignee.value.trim().toLowerCase()||null,related_post_id:el.requestRelatedPost.value||null,related_campaign_id:null,created_at:existing?.createdAt||now,updated_at:now};if(!record.title)return;const query=existing?db.from('team_requests').update(record).eq('id',existing.id):db.from('team_requests').insert(record).select().single(),result=await query;if(result.error){toast(`Could not save request: ${result.error.message}`,true);return}if(existing){const mapped=requestFromDb({...record,id:existing.id});state.requests=state.requests.map(r=>r.id===existing.id?mapped:r)}else state.requests.push(requestFromDb(result.data));closeModal(el.requestModal);renderAll();toast(existing?'Request updated.':'Request shared with the team.')}
async function updateRequestStatus(id,status){const now=new Date().toISOString(),result=await db.from('team_requests').update({status,updated_at:now}).eq('id',id);if(result.error){toast(`Could not update request: ${result.error.message}`,true);return}const item=state.requests.find(r=>r.id===id);if(item){item.status=status;item.updatedAt=now}renderRequests();updateCounts()}
async function deleteCurrentRequest(){const id=el.requestId.value;if(!id||!confirm('Delete this team request?'))return;const result=await db.from('team_requests').delete().eq('id',id);if(result.error){toast(result.error.message,true);return}state.requests=state.requests.filter(r=>r.id!==id);closeModal(el.requestModal);renderAll();toast('Request deleted.')}
function inboxPlatform(id){return platform(id)||{id:'other',name:'Other',badge:'•',color:'#71747b'}}
function renderInbox(){const q=(el.threadSearch.value||'').trim().toLowerCase(),threads=[...state.threads].sort((a,b)=>new Date(b.lastMessageAt)-new Date(a.lastMessageAt)).filter(t=>!q||[t.contactName,t.contactHandle,t.subject,t.platform].join(' ').toLowerCase().includes(q));el.threadEmpty.hidden=threads.length>0;el.threadList.innerHTML=threads.map(t=>{const p=inboxPlatform(t.platform),latest=[...state.messages].filter(m=>m.threadId===t.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0];return`<article class="thread-item ${t.id===activeThreadId?'active':''}" data-thread-id="${t.id}"><span class="network-badge" style="background:${p.color}">${p.badge}</span><div><strong>${escapeHtml(t.contactName)}</strong><small>${escapeHtml(t.contactHandle||p.name)} · ${t.status}</small><p>${escapeHtml(latest?.body||t.subject||'No messages')}</p></div><time>${formatDateTime(t.lastMessageAt,true)}</time></article>`}).join('');$$('[data-thread-id]').forEach(item=>item.addEventListener('click',()=>{activeThreadId=item.dataset.threadId;renderInbox()}));const thread=state.threads.find(t=>t.id===activeThreadId);el.conversationPlaceholder.hidden=Boolean(thread);el.activeConversation.hidden=!thread;if(!thread)return;const p=inboxPlatform(thread.platform);el.conversationPlatformBadge.textContent=p.badge;el.conversationPlatformBadge.style.background=p.color;el.conversationContact.textContent=`${thread.contactName}${thread.contactHandle?` (${thread.contactHandle})`:''}`;el.conversationSubject.textContent=thread.subject||`${p.name} conversation`;el.conversationStatus.value=thread.status;el.conversationStatus.disabled=!canCollaborate();el.messageForm.querySelectorAll('select,textarea,button').forEach(field=>field.disabled=!canCollaborate());const messages=state.messages.filter(m=>m.threadId===thread.id).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));el.messageList.innerHTML=messages.map(m=>`<div class="message-row ${m.type}"><div class="message-bubble">${escapeHtml(m.body)}</div><div class="message-meta"><span>${escapeHtml(m.senderName)}</span><time>${formatDateTime(m.createdAt,true)}</time><span>${m.type==='internal'?'Team note':m.type==='inbound'?'Customer message':'Reply record'}</span></div></div>`).join('');el.messageList.scrollTop=el.messageList.scrollHeight}
function openThreadModal(){el.threadForm.reset();openModal(el.threadModal);setTimeout(()=>el.threadContactName.focus(),50)}
async function createThread(event){event.preventDefault();if(!canCollaborate()){toast('Your role is read-only.',true);return}const now=new Date().toISOString(),threadRecord={platform:el.threadPlatform.value,contact_name:el.threadContactName.value.trim(),contact_handle:el.threadContactHandle.value.trim(),subject:el.threadSubject.value.trim(),status:'open',created_by:currentUser.id,created_at:now,updated_at:now,last_message_at:now};if(!threadRecord.contact_name)return;let result=await db.from('social_threads').insert(threadRecord).select().single();if(result.error){toast(`Could not create conversation: ${result.error.message}`,true);return}const thread=threadFromDb(result.data),messageRecord={thread_id:thread.id,message_type:'inbound',body:el.threadFirstMessage.value.trim(),sender_name:thread.contactName,sender_user_id:null,created_at:now};result=await db.from('social_messages').insert(messageRecord).select().single();if(result.error){await db.from('social_threads').delete().eq('id',thread.id);toast(`Could not save message: ${result.error.message}`,true);return}state.threads.push(thread);state.messages.push(messageFromDb(result.data));activeThreadId=thread.id;closeModal(el.threadModal);renderAll();showView('inbox');toast('Conversation added to the shared inbox.')}
async function addThreadMessage(event){event.preventDefault();if(!canCollaborate()){toast('Your role is read-only.',true);return}const thread=state.threads.find(t=>t.id===activeThreadId),body=el.messageBody.value.trim();if(!thread||!body)return;const now=new Date().toISOString(),type=el.messageType.value,record={thread_id:thread.id,message_type:type,body,sender_name:type==='inbound'?thread.contactName:currentDisplayName,sender_user_id:type==='inbound'?null:currentUser.id,created_at:now},result=await db.from('social_messages').insert(record).select().single();if(result.error){toast(`Could not add message: ${result.error.message}`,true);return}await db.from('social_threads').update({last_message_at:now,updated_at:now}).eq('id',thread.id);state.messages.push(messageFromDb(result.data));thread.lastMessageAt=now;thread.updatedAt=now;el.messageBody.value='';renderInbox();updateCounts()}
async function updateThreadStatus(){const thread=state.threads.find(t=>t.id===activeThreadId);if(!thread)return;const status=el.conversationStatus.value,now=new Date().toISOString(),result=await db.from('social_threads').update({status,updated_at:now}).eq('id',thread.id);if(result.error){toast(result.error.message,true);return}thread.status=status;thread.updatedAt=now;renderInbox();updateCounts()}
function renderCompanyPlatformPicker(){el.companyPlatformPicker.innerHTML=PLATFORMS.map(p=>`<label class="platform-option"><input type="checkbox" value="${p.id}" /><span class="network-badge" style="background:${p.color}">${p.badge}</span><strong>${p.name}</strong><i>✓</i></label>`).join('');el.companyPlatformPicker.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{selectedCompanyPlatforms=[...el.companyPlatformPicker.querySelectorAll('input:checked')].map(item=>item.value)}))}
function metricRows(values,colours={}){const max=Math.max(1,...values.map(item=>item.value));return values.map(item=>`<div class="metric-row"><span>${escapeHtml(item.label)}</span><div class="metric-bar"><i style="--metric:${Math.round(item.value/max*100)}%;--bar-colour:${colours[item.label]||'var(--red)'}"></i></div><b>${item.value}</b></div>`).join('')}
function renderAnalytics(){const published=state.posts.filter(post=>post.status==='published').length,overdue=state.posts.filter(post=>post.status!=='published'&&post.scheduledAt&&new Date(post.scheduledAt)<new Date()).length,approvalTimes=state.approvalEvents.filter(event=>event.type==='approved'),mediaTotal=state.media.reduce((sum,item)=>sum+item.size,0);el.analyticsStats.innerHTML=[['TOTAL POSTS',state.posts.length],['PUBLISHED',published],['OVERDUE',overdue],['MEDIA STORAGE',formatBytes(mediaTotal)]].map(([label,value])=>`<article><small>${label}</small><strong>${value}</strong></article>`).join('');el.platformAnalytics.innerHTML=metricRows(PLATFORMS.map(p=>({label:p.name,value:state.posts.filter(post=>post.platforms.includes(p.id)).length})),Object.fromEntries(PLATFORMS.map(p=>[p.name,p.color])));el.campaignAnalytics.innerHTML=metricRows(state.campaigns.map(c=>({label:c.name,value:state.posts.filter(post=>post.campaignId===c.id).length})),Object.fromEntries(state.campaigns.map(c=>[c.name,c.colour])));el.teamAnalytics.innerHTML=metricRows(state.team.map(member=>({label:member.display_name||member.email,value:state.audit.filter(entry=>entry.actorEmail===member.email).length})));el.workflowAnalytics.innerHTML=metricRows([{label:'Awaiting approval',value:state.posts.filter(p=>p.status==='approval').length},{label:'Ready',value:state.posts.filter(p=>p.status==='ready').length},{label:'Published',value:published},{label:'Approval decisions',value:approvalTimes.length}])}
function downloadCSV(filename,headers,rows){const escape=value=>`"${String(value??'').replaceAll('"','""')}"`,csv=[headers.map(escape).join(','),...rows.map(row=>row.map(escape).join(','))].join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function downloadAnalyticsCSV(){downloadCSV(`tech-social-analytics-${toLocalDate(new Date())}.csv`,['Post','Status','Platforms','Campaign','Scheduled'],state.posts.map(post=>[postTitle(post),post.status,post.platforms.join('|'),campaign(post.campaignId)?.name||'',post.scheduledAt||'']))}
function combinedActivity(){return[...state.audit,...state.loginEvents.map(item=>({id:`login-${item.id}`,actorEmail:item.email,action:'logged in',entityType:'login_events',entityId:String(item.id),summary:`${item.displayName} signed in as ${item.role}`,createdAt:item.createdAt}))].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))}
function renderActivity(){const q=(el.activitySearch.value||'').toLowerCase(),type=el.activityTypeFilter.value,items=combinedActivity().filter(item=>(type==='all'||item.entityType===type)&&(!q||[item.actorEmail,item.action,item.entityType,item.summary].join(' ').toLowerCase().includes(q)));el.activityList.innerHTML=items.map(item=>`<article class="activity-row"><span>${item.entityType==='login_events'?'L':item.action.slice(0,1).toUpperCase()}</span><div><strong>${escapeHtml(item.actorEmail)} ${escapeHtml(item.action)} ${item.entityType==='login_events'?'':' '+escapeHtml(item.entityType)}</strong><small>${escapeHtml(item.summary||item.entityId)}</small></div><time>${formatDateTime(item.createdAt,true)}</time></article>`).join('')||'<div class="thread-empty">No login or change activity recorded yet.</div>'}
function downloadAuditCSV(){downloadCSV(`tech-social-login-change-log-${toLocalDate(new Date())}.csv`,['Time','User','Action','Entity','ID','Summary'],combinedActivity().map(item=>[item.createdAt,item.actorEmail,item.action,item.entityType,item.entityId,item.summary]))}
function renderBackups(){el.backupsEmpty.hidden=state.backups.length>0;el.backupList.innerHTML=state.backups.map(item=>`<article class="backup-row"><span><svg viewBox="0 0 24 24"><path d="M4 5h16v14H4Z"/><path d="M8 5v5h8V5"/></svg></span><div><strong>${escapeHtml(item.label)}</strong><small>${item.type} · Created ${formatDateTime(item.createdAt)} · Expires ${formatDateTime(item.expiresAt,true)}</small></div><div class="backup-row-actions"><button type="button" data-download-backup="${item.id}">Download</button><button type="button" data-delete-backup="${item.id}">Delete</button></div></article>`).join('');$$('[data-download-backup]').forEach(button=>button.addEventListener('click',()=>downloadBackup(button.dataset.downloadBackup)));$$('[data-delete-backup]').forEach(button=>button.addEventListener('click',()=>deleteBackup(button.dataset.deleteBackup)))}
async function createBackup(){if(!hasRole('admin'))return;const result=await db.rpc('create_backup_snapshot',{p_label:`Manual backup ${new Date().toLocaleString('en-GB')}`,p_type:'manual'});if(result.error){toast(result.error.message,true);return}await loadCloudData();renderBackups();toast('Backup restore point created.')}
function downloadBackup(id){const item=state.backups.find(backup=>backup.id===id);if(!item)return;const blob=new Blob([JSON.stringify(item.snapshot,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`tech-social-restore-${item.createdAt.slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
async function deleteBackup(id){if(!hasRole('admin')||!confirm('Delete this restore point?'))return;const result=await db.from('backup_snapshots').delete().eq('id',id);if(result.error){toast(result.error.message,true);return}state.backups=state.backups.filter(item=>item.id!==id);renderBackups()}
async function saveCompanySettings(event){event.preventDefault();if(!hasRole('admin'))return;const record={company_name:el.companyName.value.trim(),website_url:el.companyWebsite.value.trim(),default_hashtags:el.companyHashtags.value.trim(),default_platforms:selectedCompanyPlatforms,timezone:el.companyTimezone.value,working_hours_start:el.companyStart.value,working_hours_end:el.companyEnd.value,primary_colour:el.companyColour.value,footer_text:el.companyFooter.value.trim(),logo_media_id:el.companyLogo.value||null,updated_at:new Date().toISOString(),updated_by:currentUser.id},result=await db.from('company_settings').update(record).eq('id',1);if(result.error){el.companyMessage.textContent=result.error.message;el.companyMessage.classList.add('error');return}state.company={id:1,...record};document.documentElement.style.setProperty('--red',record.primary_colour);el.companyMessage.textContent='Company settings saved.';el.companyMessage.classList.remove('error')}
function showSettingsTab(tab){$$('[data-settings-tab]').forEach(button=>button.classList.toggle('active',button.dataset.settingsTab===tab));$$('[data-settings-pane]').forEach(pane=>{pane.hidden=pane.dataset.settingsPane!==tab;pane.classList.toggle('active',pane.dataset.settingsPane===tab)})}
function renderSettings(){el.profileDisplayName.value=currentDisplayName;el.profileEmail.value=currentUser?.email||'';el.profileAvatar.textContent=(currentDisplayName||'TL').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const roleLabels={admin:'Administrator',editor:'Editor',approver:'Approver',viewer:'Viewer'};el.profileRoleBadge.textContent=roleLabels[currentUserRole]||currentUserRole;el.teamMemberList.innerHTML=state.team.map(member=>`<article class="team-member-row ${member.email===currentUser?.email?.toLowerCase()?'is-self':''}"><div><strong>${escapeHtml(member.display_name||member.email)}</strong><small>${escapeHtml(member.email)}${member.email===currentUser?.email?.toLowerCase()?' · You':''}</small></div><select data-team-role="${escapeHtml(member.email)}" ${member.email===currentUser?.email?.toLowerCase()?'disabled':''}><option value="viewer" ${member.role==='viewer'?'selected':''}>Viewer</option><option value="editor" ${member.role==='editor'?'selected':''}>Editor</option><option value="approver" ${member.role==='approver'?'selected':''}>Approver</option><option value="admin" ${member.role==='admin'?'selected':''}>Administrator</option></select><button data-remove-member="${escapeHtml(member.email)}" type="button" aria-label="Remove">×</button></article>`).join('');$$('[data-team-role]').forEach(select=>select.addEventListener('change',()=>updateTeamRole(select.dataset.teamRole,select.value)));$$('[data-remove-member]').forEach(button=>button.addEventListener('click',()=>removeTeamMember(button.dataset.removeMember)));const company=state.company||{};el.companyName.value=company.company_name||'Tech Lab';el.companyWebsite.value=company.website_url||DEFAULT_POST_URL;el.companyHashtags.value=company.default_hashtags||'';selectedCompanyPlatforms=company.default_platforms||['instagram','facebook'];el.companyPlatformPicker.querySelectorAll('input').forEach(input=>input.checked=selectedCompanyPlatforms.includes(input.value));el.companyTimezone.value=company.timezone||'Europe/London';el.companyColour.value=company.primary_colour||'#ef111b';el.companyStart.value=(company.working_hours_start||'09:00').slice(0,5);el.companyEnd.value=(company.working_hours_end||'17:30').slice(0,5);el.companyFooter.value=company.footer_text||'Where Tech Meets Social';el.companyLogo.innerHTML='<option value="">Default Tech Social logo</option>'+state.media.filter(item=>item.type==='image'&&!item.archived).map(item=>`<option value="${item.id}">${escapeHtml(item.name)}</option>`).join('');el.companyLogo.value=company.logo_media_id||'';el.companySettingsForm.querySelectorAll('input,select,button').forEach(field=>field.disabled=!hasRole('admin'));el.metaCallbackUrl.textContent=`${window.TECH_SOCIAL_CONFIG.supabaseUrl}/functions/v1/meta-webhook`;const metaConnected=state.connections.some(connection=>['facebook','instagram'].includes(connection.platform)&&connection.status==='connected');el.connectMetaButton.textContent=metaConnected?'Reconnect Meta accounts':'Connect Facebook & Instagram';el.connectionsGrid.innerHTML=PLATFORMS.map(p=>{const connection=state.connections.find(item=>item.platform===p.id),supported=['facebook','instagram'].includes(p.id),connected=connection?.status==='connected';return`<article class="connection-card"><span class="network-badge" style="background:${p.color}">${p.badge}</span><div><strong>${p.name}</strong><small>${connected?`${escapeHtml(connection.accountName||connection.externalAccountId)} · Last event ${connection.lastEventAt?formatDateTime(connection.lastEventAt,true):'not received'}`:supported?'Meta webhook setup required':'Manual inbox · API connector not installed'}</small></div><i class="${connected?'connected':''}"></i></article>`}).join('');el.versionHistory.innerHTML=VERSION_HISTORY.map((release,index)=>`<article class="version-card ${index===0?'current':''}"><header><h4>Version ${release.version}${index===0?' · Current':''}</h4><time>${release.date}</time></header><p>${release.summary}</p><ul>${release.changes.map(change=>`<li>${escapeHtml(change)}</li>`).join('')}</ul></article>`).join('')}
async function saveProfile(event){event.preventDefault();const name=el.profileDisplayName.value.trim();if(!name)return;const result=await db.rpc('update_own_profile',{p_display_name:name});if(result.error){el.profileMessage.textContent=result.error.message;el.profileMessage.classList.add('error');return}currentDisplayName=name;const initials=name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();el.userDisplayName.textContent=name;el.userInitials.textContent=initials;el.workspaceInitials.textContent=initials;el.workspaceName.textContent=`${name.trim().split(/\s+/)[0]}'s workspace`;el.profileAvatar.textContent=initials;setDateGreeting();el.profileMessage.textContent='Profile updated for your account.';el.profileMessage.classList.remove('error')}
async function addTeamMember(event){event.preventDefault();if(!hasRole('admin'))return;const email=el.teamMemberEmail.value.trim().toLowerCase(),name=el.teamMemberName.value.trim(),role=el.teamMemberRole.value;if(!email||!name)return;const result=await db.from('allowed_users').insert({email,display_name:name,role});if(result.error){el.teamMessage.textContent=result.error.message;el.teamMessage.classList.add('error');return}el.teamAddForm.reset();el.teamMessage.textContent=`${name} added as ${role}. They can now create a login with this email.`;el.teamMessage.classList.remove('error');await loadCloudData();renderAll()}
async function updateTeamRole(email,role){if(!hasRole('admin')||email===currentUser.email.toLowerCase())return;const result=await db.from('allowed_users').update({role}).eq('email',email);if(result.error){toast(`Could not update role: ${result.error.message}`,true);return}await loadCloudData();renderAll();toast(`Role updated to ${role}.`)}
async function removeTeamMember(email){if(!hasRole('admin')||email===currentUser.email.toLowerCase()||!confirm(`Remove ${email} from Tech Social CRM?`))return;const result=await db.from('allowed_users').delete().eq('email',email);if(result.error){toast(`Could not remove member: ${result.error.message}`,true);return}await loadCloudData();renderAll();toast('Team member access removed.')}
async function changePassword(event){event.preventDefault();if(el.newPassword.value!==el.confirmPassword.value){el.passwordMessage.textContent='The passwords do not match.';el.passwordMessage.classList.add('error');return}const result=await db.auth.updateUser({password:el.newPassword.value});if(result.error){el.passwordMessage.textContent=result.error.message;el.passwordMessage.classList.add('error');return}el.passwordForm.reset();el.passwordMessage.textContent='Password changed successfully.';el.passwordMessage.classList.remove('error')}
function compareVersions(a,b){const pa=String(a).split('.').map(Number),pb=String(b).split('.').map(Number);for(let i=0;i<Math.max(pa.length,pb.length);i++){if((pa[i]||0)!==(pb[i]||0))return(pa[i]||0)-(pb[i]||0)}return 0}
function setUpdateAvailability(ready,label){el.updateNowButton.disabled=!ready;el.updateAvailability.textContent=label;el.updateAvailability.classList.toggle('available',ready);el.updateAvailability.classList.toggle('unavailable',!ready)}
async function checkForUpdates(){el.checkVersionButton.disabled=true;el.versionStatus.textContent='Checking for updates…';setUpdateAvailability(false,'CHECKING');try{const response=await fetch(`version.json?time=${Date.now()}`,{cache:'no-store'});if(!response.ok)throw new Error('Version information unavailable.');const info=await response.json(),ready=compareVersions(info.version,APP_VERSION)>0;availableVersion=ready?info.version:'';el.versionStatus.textContent=ready?`Version ${info.version} is deployed and ready to install.`:`You are up to date on version ${APP_VERSION}.`;setUpdateAvailability(ready,ready?'UPDATE READY':'NO UPDATE')}catch(error){availableVersion='';el.versionStatus.textContent=error.message;setUpdateAvailability(false,'CHECK FAILED')}finally{el.checkVersionButton.disabled=false}}
async function installAvailableUpdate(){if(!availableVersion||el.updateNowButton.disabled)return;el.updateNowButton.disabled=true;setUpdateAvailability(false,'INSTALLING');el.versionStatus.textContent=`Installing version ${availableVersion}…`;localStorage.setItem('tech-social-pending-update',availableVersion);try{if('serviceWorker'in navigator){const registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.map(registration=>registration.unregister()))}if('caches'in window){const keys=await caches.keys();await Promise.all(keys.map(key=>caches.delete(key)))}}catch{}const url=new URL(location.href);url.searchParams.set('updated',Date.now());location.replace(url.toString())}
function handleInstalledUpdateNotice(){const expected=localStorage.getItem('tech-social-pending-update');if(!expected)return;if(compareVersions(APP_VERSION,expected)>=0){localStorage.removeItem('tech-social-pending-update');setTimeout(()=>toast(`Tech Social updated successfully to version ${APP_VERSION}.`),500)}}

async function startMetaOAuth(){el.connectMetaButton.disabled=true;el.connectMetaButton.textContent='Opening Meta…';const returnUrl=`${location.origin}${location.pathname}`;const{data,error}=await db.functions.invoke('meta-oauth-start',{body:{returnUrl}});if(error||!data?.authorizationUrl){toast(`Could not start Meta connection: ${error?.message||data?.error||'Unknown error'}`,true);el.connectMetaButton.disabled=false;el.connectMetaButton.textContent='Connect Facebook & Instagram';return}location.href=data.authorizationUrl}
function handleProviderCallbackNotice(){const params=new URLSearchParams(location.search),connected=params.get('meta_connected'),error=params.get('meta_error');if(connected){toast(`${connected} Meta ${connected==='1'?'account':'accounts'} connected securely.`);showView('settings');showSettingsTab('connections')}else if(error){toast(`Meta connection failed: ${error}`,true)}if(connected||error){history.replaceState({},document.title,`${location.origin}${location.pathname}`)}}
async function publishConnectedMeta(){if(!canPublishContent()){toast('Approver permission is required to publish.',true);return}const post=state.posts.find(item=>item.id===publishingPostId);if(!post)return;const platforms=post.platforms.filter(id=>['facebook','instagram'].includes(id)&&state.connections.some(connection=>connection.platform===id&&connection.status==='connected'));if(!platforms.length){toast('No selected Meta destination is connected. Open Settings → Connections first.',true);return}el.publishMetaButton.disabled=true;el.publishMetaButton.textContent='Publishing…';const{data,error}=await db.functions.invoke('publish-meta',{body:{postId:post.id,platforms}});el.publishMetaButton.disabled=false;el.publishMetaButton.textContent='Publish connected Meta accounts';if(error){toast(`Automatic publishing failed: ${error.message}`,true);return}const failed=(data?.results||[]).filter(result=>result.status==='failed');if(failed.length){toast(failed.map(result=>`${result.platform}: ${result.error}`).join(' · '),true)}else{toast(`${platforms.join(' and ')} published successfully.`);if(data.complete){post.status='published';closeModal(el.publishModal)}await loadCloudData();renderAll()}}

function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`tech-social-crm-backup-${toLocalDate(new Date())}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),500);toast('CRM backup downloaded.')}
function importData(){const file=el.importInput.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=async()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.posts)||!Array.isArray(data.campaigns))throw new Error('Invalid backup format.');if(!confirm('Replace the shared CRM data with this backup for every team member?'))return;const campaigns=data.campaigns.map(c=>({...c,updatedAt:c.updatedAt||new Date().toISOString()})),posts=data.posts.map(p=>({...p,createdAt:p.createdAt||new Date().toISOString(),updatedAt:p.updatedAt||new Date().toISOString()})),accounts={...Object.fromEntries(PLATFORMS.map(p=>[p.id,false])),...(data.accounts||{})};let result=await db.from('posts').delete().not('id','is',null);if(result.error)throw result.error;result=await db.from('campaigns').delete().not('id','is',null);if(result.error)throw result.error;if(campaigns.length){result=await db.from('campaigns').upsert(campaigns.map(campaignToDb));if(result.error)throw result.error}if(posts.length){result=await db.from('posts').upsert(posts.map(postToDb));if(result.error)throw result.error}result=await db.from('social_accounts').upsert(PLATFORMS.map(p=>({platform:p.id,ready:Boolean(accounts[p.id]),updated_at:new Date().toISOString(),updated_by:currentUser.id})));if(result.error)throw result.error;state={posts,campaigns,templates:state.templates,media:state.media,folders:state.folders,ideas:state.ideas,approvalEvents:state.approvalEvents,recurring:state.recurring,audit:state.audit,loginEvents:state.loginEvents,backups:state.backups,company:state.company,requests:state.requests,threads:state.threads,messages:state.messages,connections:state.connections,team:state.team,notifications:state.notifications,notificationReads:state.notificationReads,accounts};renderAll();toast('Shared CRM backup imported. Media files already in the library were preserved.')}catch(error){toast(error.message||'That file is not a valid Tech Social CRM backup.',true)}finally{el.importInput.value=''}};reader.readAsText(file)}
function openModal(modal){modal.hidden=false;document.body.style.overflow='hidden'}function closeModal(modal){modal.hidden=true;if(!$$('.modal-backdrop:not([hidden])').length)document.body.style.overflow=''}
function toast(message,warning=false){const n=document.createElement('div');n.className=`toast${warning?' warning':''}`;n.textContent=message;el.toastRegion.appendChild(n);setTimeout(()=>n.remove(),3500)}

initializeAuth();
